), resolved as (
  select
    c.*,
    r.item_id as actual_item_id,
    coalesce(r.resolution_status, 'no_match') as actual_status,
    r.match_method as actual_match_method,
    coalesce(r.candidate_count, 0)::integer as actual_candidate_count
  from cases c
  left join lateral (
    select x.*, count(*) over ()::integer as candidate_count
    from catalog.resolve_items_v6(c.query, 'health_diagnostics', null, 10) x
    order by x.result_rank
    limit 1
  ) r on true
)
select * from resolved;

select extensions.plan(10);
select extensions.is((select count(*)::integer from resolver_benchmark_results), 200, 'benchmark contains the reviewed 100-200 cases');
select extensions.is((select count(*)::integer from resolver_benchmark_results where expected_status = 'resolved'), 184, 'safe variant cases are present');
select extensions.is((select count(*)::integer from resolver_benchmark_results where case_id like 'panels_%'), 4, 'panel ambiguity cases are present');
select extensions.is((select count(*)::integer from resolver_benchmark_results where case_id like 'underspecified_%'), 8, 'underspecified cases are present');
select extensions.is((select count(*)::integer from resolver_benchmark_results where case_id like 'negative_%'), 4, 'negative/adversarial cases are present');
select extensions.is((select count(*)::integer from resolver_benchmark_results where expected_status = 'resolved' and actual_status = 'resolved'), 184, 'every safe variant resolves');
select extensions.is((select count(*)::integer from resolver_benchmark_results where expected_status = 'resolved' and actual_item_id::text = expected_item_id), 184, 'every safe variant resolves to its reviewed item');
select extensions.is((select count(*)::integer from resolver_benchmark_results where expected_status = 'resolved' and actual_match_method = any(allowed_match_methods)), 184, 'every safe variant has exact or approved-alias evidence');
select extensions.is((select count(*)::integer from resolver_benchmark_results where expected_status = 'abstain' and actual_status = any(allowed_statuses)), 16, 'every ambiguous or unrelated query abstains safely');
select extensions.is((select count(*)::integer from resolver_benchmark_results where case_id like 'negative_%' and actual_status = 'no_match'), 4, 'adversarial and unrelated input returns no_match');
select * from extensions.finish();


commit;
